-- Candidate only: one audited, non-replayable provider attempt per action.
-- No physical row position or provider cell values are persisted. A D1
-- state machine cannot prove that a Sheets request has stopped or that editors
-- are excluded: external coordination is mandatory before any dispatch.
CREATE TABLE personal_historical_marker_actions (
  action_id TEXT NOT NULL PRIMARY KEY,
  spreadsheet_id TEXT NOT NULL,
  sheet_name TEXT NOT NULL,
  personal_use_id TEXT NOT NULL,
  metadata_id INTEGER NOT NULL CHECK(metadata_id BETWEEN 1 AND 2147483647),
  source_version INTEGER NOT NULL CHECK(source_version>0),
  source_revision INTEGER NOT NULL CHECK(source_revision>0),
  source_fingerprint TEXT NOT NULL CHECK(length(source_fingerprint)=64 AND source_fingerprint NOT GLOB '*[^0-9a-f]*'),
  cutover_generation TEXT NOT NULL,
  operation_token TEXT NOT NULL,
  outer_token TEXT NOT NULL,
  remediation_token TEXT NOT NULL CHECK(length(remediation_token) BETWEEN 16 AND 128),
  kind TEXT NOT NULL CHECK(kind IN ('ATTACH_ABSENT','DELETE_WRONG_ROW')),
  evidence_digest TEXT NOT NULL CHECK(length(evidence_digest)=64 AND evidence_digest NOT GLOB '*[^0-9a-f]*'),
  post_digest TEXT CHECK(post_digest IS NULL OR (length(post_digest)=64 AND post_digest NOT GLOB '*[^0-9a-f]*')),
  principal TEXT NOT NULL CHECK(principal='ADMIN_TOKEN'),
  reason TEXT NOT NULL CHECK(length(reason) BETWEEN 5 AND 200),
  state TEXT NOT NULL CHECK(state IN ('APPROVED','DISPATCHED','REVIEW','VERIFIED','CANCELLED')),
  created_at TEXT NOT NULL,
  expires_at TEXT NOT NULL CHECK(expires_at>created_at),
  updated_at TEXT NOT NULL,
  CHECK((state='VERIFIED' AND post_digest IS NOT NULL) OR (state<>'VERIFIED' AND post_digest IS NULL))
);
-- All unresolved marker operations block the whole personal sheet, including
-- a different entity or metadata id. REVIEW is deliberately non-releasable.
CREATE UNIQUE INDEX personal_historical_marker_one_open ON personal_historical_marker_actions(spreadsheet_id,sheet_name) WHERE state IN ('APPROVED','DISPATCHED','REVIEW');
CREATE TABLE personal_historical_marker_atomic_assertions(assertion_id TEXT PRIMARY KEY,ok INTEGER NOT NULL CHECK(ok=1));

CREATE TRIGGER historical_marker_action_admit BEFORE INSERT ON personal_historical_marker_actions
WHEN NEW.state<>'APPROVED' OR NEW.post_digest IS NOT NULL OR length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR length(NEW.expires_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.expires_at) IS NOT NEW.expires_at OR length(NEW.updated_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.updated_at) IS NOT NEW.updated_at OR NEW.updated_at<>NEW.created_at OR abs((julianday(NEW.created_at)-julianday('now'))*86400)>60 OR NOT EXISTS(
 SELECT 1 FROM personal_historical_enrollment_intents i
 JOIN personal_raw_enrollment_locks l ON l.spreadsheet_id=i.spreadsheet_id AND l.sheet_name=i.sheet_name AND l.personal_use_id=i.personal_use_id AND l.metadata_id=i.metadata_id AND l.operation_token=i.operation_token AND l.outer_token=i.outer_token AND l.cutover_generation=i.cutover_generation AND l.state='REVIEW'
 JOIN sheet_metadata_identity_registry m ON m.spreadsheet_id=i.spreadsheet_id AND m.sheet_name=i.sheet_name AND m.metadata_id=i.metadata_id AND m.entity_kind='PERSONAL_USE' AND m.entity_id=i.personal_use_id
 JOIN owner_personal_transactions p ON p.personal_use_id=i.personal_use_id AND p.version=i.source_version AND p.status='CONFIRMED' AND substr(p.transaction_date,1,7)=i.month
 JOIN personal_projection_source_revisions r ON r.personal_use_id=p.personal_use_id AND r.revision=i.source_revision AND r.state='TRACKED'
 JOIN personal_projection_admissions d ON d.personal_use_id=i.personal_use_id AND d.sequence=i.admission_sequence
 JOIN personal_projection_cutovers c ON c.spreadsheet_id=i.spreadsheet_id AND c.sheet_name=i.sheet_name AND c.generation=i.cutover_generation AND c.admission_watermark=i.admission_watermark AND c.state='ACTIVE'
 JOIN personal_legacy_writer_gates g ON g.spreadsheet_id=c.spreadsheet_id AND g.sheet_name=c.sheet_name AND g.generation=c.generation AND g.state='HOLD'
 WHERE i.spreadsheet_id=NEW.spreadsheet_id AND i.sheet_name=NEW.sheet_name AND i.personal_use_id=NEW.personal_use_id AND i.metadata_id=NEW.metadata_id AND i.source_version=NEW.source_version AND i.source_revision=NEW.source_revision AND i.source_fingerprint=NEW.source_fingerprint AND i.cutover_generation=NEW.cutover_generation AND i.operation_token=NEW.operation_token AND i.outer_token=NEW.outer_token AND i.state='REVIEW' AND i.admission_sequence<=i.admission_watermark
 AND julianday(i.updated_at)<=julianday('now','-15 minutes') AND julianday(l.updated_at)<=julianday('now','-15 minutes')
 AND NOT EXISTS(SELECT 1 FROM sync_jobs s WHERE s.entity_type='PERSONAL_USE' AND (s.status='PROCESSING' OR (s.entity_key=i.personal_use_id AND s.status='REVIEW')))
 AND NOT EXISTS(SELECT 1 FROM personal_raw_identity_intents p2 WHERE p2.spreadsheet_id=i.spreadsheet_id AND p2.sheet_name=i.sheet_name AND (p2.personal_use_id=i.personal_use_id OR p2.state='IN_FLIGHT')) AND NOT EXISTS(SELECT 1 FROM personal_projection_generation_observations seen WHERE seen.spreadsheet_id=i.spreadsheet_id AND seen.personal_use_id=i.personal_use_id AND (seen.source_revision>i.source_revision OR seen.source_version>i.source_version OR (seen.state='REVIEW' AND NOT (COALESCE(seen.reason,'')='HISTORICAL_IDENTITY_UNVERIFIED' AND seen.cutover_generation=i.cutover_generation AND seen.source_version=i.source_version AND seen.source_revision=i.source_revision)))) AND NOT EXISTS(SELECT 1 FROM personal_projection_generation_jobs seen WHERE seen.spreadsheet_id=i.spreadsheet_id AND seen.personal_use_id=i.personal_use_id AND (seen.source_revision>i.source_revision OR seen.source_version>i.source_version OR seen.state='IN_FLIGHT' OR (seen.state='REVIEW' AND NOT (COALESCE(seen.reason,'')='HISTORICAL_IDENTITY_UNVERIFIED' AND seen.cutover_generation=i.cutover_generation AND seen.source_version=i.source_version AND seen.source_revision=i.source_revision)))) AND NOT EXISTS(SELECT 1 FROM personal_projection_runtime_intents o WHERE o.spreadsheet_id=i.spreadsheet_id AND o.personal_use_id=i.personal_use_id AND o.state IN ('IN_FLIGHT','REVIEW'))
 AND NOT EXISTS(SELECT 1 FROM personal_historical_recovery_actions a WHERE a.spreadsheet_id=i.spreadsheet_id AND a.sheet_name=i.sheet_name AND a.personal_use_id=i.personal_use_id AND a.state='APPROVED')
) OR NOT EXISTS(SELECT 1 FROM personal_historical_marker_atomic_assertions x WHERE x.assertion_id=NEW.action_id AND x.ok=1) OR NOT EXISTS(SELECT 1 FROM admin_audit audit WHERE audit.action='HISTORICAL_MARKER_APPROVED' AND audit.entity_key=NEW.personal_use_id AND CASE WHEN json_valid(audit.after_json) THEN json_extract(audit.after_json,'$.actionId')=NEW.action_id ELSE 0 END )
BEGIN SELECT RAISE(ABORT,'HISTORICAL_MARKER_APPROVAL_REQUIRED'); END;

CREATE TRIGGER historical_marker_action_no_delete BEFORE DELETE ON personal_historical_marker_actions BEGIN SELECT RAISE(ABORT,'HISTORICAL_MARKER_AUDIT_REQUIRED'); END;
CREATE TRIGGER historical_marker_action_no_replace BEFORE INSERT ON personal_historical_marker_actions WHEN EXISTS(SELECT 1 FROM personal_historical_marker_actions a WHERE a.rowid=NEW.rowid OR a.action_id=NEW.action_id) BEGIN SELECT RAISE(ABORT,'HISTORICAL_MARKER_AUDIT_REQUIRED'); END;
CREATE TRIGGER historical_marker_action_no_rowid_replace BEFORE UPDATE ON personal_historical_marker_actions WHEN EXISTS(SELECT 1 FROM personal_historical_marker_actions a WHERE a.rowid=NEW.rowid AND a.rowid<>OLD.rowid) BEGIN SELECT RAISE(ABORT,'HISTORICAL_MARKER_AUDIT_REQUIRED'); END;
CREATE TRIGGER historical_marker_action_immutable BEFORE UPDATE OF action_id,spreadsheet_id,sheet_name,personal_use_id,metadata_id,source_version,source_revision,source_fingerprint,cutover_generation,operation_token,outer_token,remediation_token,kind,evidence_digest,principal,reason,created_at,expires_at ON personal_historical_marker_actions BEGIN SELECT RAISE(ABORT,'HISTORICAL_MARKER_AUDIT_REQUIRED'); END;
CREATE TRIGGER historical_marker_action_post_digest BEFORE UPDATE OF post_digest ON personal_historical_marker_actions WHEN OLD.post_digest IS NOT NEW.post_digest AND NOT (OLD.state='DISPATCHED' AND NEW.state='VERIFIED' AND OLD.post_digest IS NULL AND NEW.post_digest IS NOT NULL) BEGIN SELECT RAISE(ABORT,'HISTORICAL_MARKER_AUDIT_REQUIRED'); END;

CREATE TRIGGER historical_marker_action_transition BEFORE UPDATE OF state,updated_at ON personal_historical_marker_actions
WHEN OLD.state IS NOT NEW.state AND NOT (
 (OLD.state='APPROVED' AND NEW.state='DISPATCHED' AND OLD.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')
   AND EXISTS(SELECT 1 FROM personal_historical_enrollment_intents i JOIN personal_raw_enrollment_locks l ON l.spreadsheet_id=i.spreadsheet_id AND l.sheet_name=i.sheet_name AND l.personal_use_id=i.personal_use_id AND l.metadata_id=i.metadata_id AND l.operation_token=i.operation_token AND l.outer_token=i.outer_token AND l.cutover_generation=i.cutover_generation AND l.state='REVIEW' JOIN sheet_metadata_identity_registry m ON m.spreadsheet_id=i.spreadsheet_id AND m.sheet_name=i.sheet_name AND m.metadata_id=i.metadata_id AND m.entity_kind='PERSONAL_USE' AND m.entity_id=i.personal_use_id JOIN owner_personal_transactions p ON p.personal_use_id=i.personal_use_id AND p.version=i.source_version AND p.status='CONFIRMED' JOIN personal_projection_source_revisions r ON r.personal_use_id=p.personal_use_id AND r.revision=i.source_revision AND r.state='TRACKED' JOIN personal_projection_cutovers c ON c.spreadsheet_id=i.spreadsheet_id AND c.sheet_name=i.sheet_name AND c.generation=i.cutover_generation AND c.admission_watermark=i.admission_watermark AND c.state='ACTIVE' JOIN personal_legacy_writer_gates g ON g.spreadsheet_id=c.spreadsheet_id AND g.sheet_name=c.sheet_name AND g.generation=c.generation AND g.state='HOLD' WHERE i.spreadsheet_id=OLD.spreadsheet_id AND i.sheet_name=OLD.sheet_name AND i.personal_use_id=OLD.personal_use_id AND i.metadata_id=OLD.metadata_id AND i.source_version=OLD.source_version AND i.source_revision=OLD.source_revision AND i.source_fingerprint=OLD.source_fingerprint AND i.cutover_generation=OLD.cutover_generation AND i.operation_token=OLD.operation_token AND i.outer_token=OLD.outer_token AND i.state='REVIEW' AND julianday(i.updated_at)<=julianday('now','-15 minutes') AND julianday(l.updated_at)<=julianday('now','-15 minutes') AND NOT EXISTS(SELECT 1 FROM sync_jobs s WHERE s.entity_type='PERSONAL_USE' AND (s.status='PROCESSING' OR (s.entity_key=i.personal_use_id AND s.status='REVIEW'))) AND NOT EXISTS(SELECT 1 FROM personal_raw_identity_intents p2 WHERE p2.spreadsheet_id=i.spreadsheet_id AND p2.sheet_name=i.sheet_name AND (p2.personal_use_id=i.personal_use_id OR p2.state='IN_FLIGHT')) AND NOT EXISTS(SELECT 1 FROM personal_projection_generation_observations seen WHERE seen.spreadsheet_id=i.spreadsheet_id AND seen.personal_use_id=i.personal_use_id AND (seen.source_revision>i.source_revision OR seen.source_version>i.source_version OR (seen.state='REVIEW' AND NOT (COALESCE(seen.reason,'')='HISTORICAL_IDENTITY_UNVERIFIED' AND seen.cutover_generation=i.cutover_generation AND seen.source_version=i.source_version AND seen.source_revision=i.source_revision)))) AND NOT EXISTS(SELECT 1 FROM personal_projection_generation_jobs seen WHERE seen.spreadsheet_id=i.spreadsheet_id AND seen.personal_use_id=i.personal_use_id AND (seen.source_revision>i.source_revision OR seen.source_version>i.source_version OR seen.state='IN_FLIGHT' OR (seen.state='REVIEW' AND NOT (COALESCE(seen.reason,'')='HISTORICAL_IDENTITY_UNVERIFIED' AND seen.cutover_generation=i.cutover_generation AND seen.source_version=i.source_version AND seen.source_revision=i.source_revision)))) AND NOT EXISTS(SELECT 1 FROM personal_projection_runtime_intents o WHERE o.spreadsheet_id=i.spreadsheet_id AND o.personal_use_id=i.personal_use_id AND o.state IN ('IN_FLIGHT','REVIEW')))) OR
 (OLD.state='DISPATCHED' AND NEW.state='VERIFIED' AND NEW.post_digest IS NOT NULL AND EXISTS(SELECT 1 FROM personal_historical_enrollment_intents i JOIN personal_raw_enrollment_locks l ON l.spreadsheet_id=i.spreadsheet_id AND l.sheet_name=i.sheet_name AND l.personal_use_id=i.personal_use_id AND l.metadata_id=i.metadata_id AND l.operation_token=i.operation_token AND l.outer_token=i.outer_token AND l.cutover_generation=i.cutover_generation AND l.state='REVIEW' JOIN sheet_metadata_identity_registry m ON m.spreadsheet_id=i.spreadsheet_id AND m.sheet_name=i.sheet_name AND m.metadata_id=i.metadata_id AND m.entity_kind='PERSONAL_USE' AND m.entity_id=i.personal_use_id JOIN owner_personal_transactions p ON p.personal_use_id=i.personal_use_id AND p.version=i.source_version AND p.status='CONFIRMED' JOIN personal_projection_source_revisions r ON r.personal_use_id=p.personal_use_id AND r.revision=i.source_revision AND r.state='TRACKED' JOIN personal_projection_cutovers c ON c.spreadsheet_id=i.spreadsheet_id AND c.sheet_name=i.sheet_name AND c.generation=i.cutover_generation AND c.admission_watermark=i.admission_watermark AND c.state='ACTIVE' JOIN personal_legacy_writer_gates g ON g.spreadsheet_id=c.spreadsheet_id AND g.sheet_name=c.sheet_name AND g.generation=c.generation AND g.state='HOLD' WHERE i.spreadsheet_id=OLD.spreadsheet_id AND i.sheet_name=OLD.sheet_name AND i.personal_use_id=OLD.personal_use_id AND i.metadata_id=OLD.metadata_id AND i.source_version=OLD.source_version AND i.source_revision=OLD.source_revision AND i.source_fingerprint=OLD.source_fingerprint AND i.cutover_generation=OLD.cutover_generation AND i.operation_token=OLD.operation_token AND i.outer_token=OLD.outer_token AND i.state='REVIEW' AND julianday(i.updated_at)<=julianday('now','-15 minutes') AND julianday(l.updated_at)<=julianday('now','-15 minutes') AND NOT EXISTS(SELECT 1 FROM sync_jobs busy WHERE busy.entity_type='PERSONAL_USE' AND (busy.status='PROCESSING' OR (busy.entity_key=i.personal_use_id AND busy.status='REVIEW'))) AND NOT EXISTS(SELECT 1 FROM personal_raw_identity_intents p2 WHERE p2.spreadsheet_id=i.spreadsheet_id AND p2.sheet_name=i.sheet_name AND (p2.personal_use_id=i.personal_use_id OR p2.state='IN_FLIGHT')) AND NOT EXISTS(SELECT 1 FROM personal_projection_generation_observations seen WHERE seen.spreadsheet_id=i.spreadsheet_id AND seen.personal_use_id=i.personal_use_id AND (seen.source_revision>i.source_revision OR seen.source_version>i.source_version OR (seen.state='REVIEW' AND NOT (COALESCE(seen.reason,'')='HISTORICAL_IDENTITY_UNVERIFIED' AND seen.cutover_generation=i.cutover_generation AND seen.source_version=i.source_version AND seen.source_revision=i.source_revision)))) AND NOT EXISTS(SELECT 1 FROM personal_projection_generation_jobs seen WHERE seen.spreadsheet_id=i.spreadsheet_id AND seen.personal_use_id=i.personal_use_id AND (seen.source_revision>i.source_revision OR seen.source_version>i.source_version OR seen.state='IN_FLIGHT' OR (seen.state='REVIEW' AND NOT (COALESCE(seen.reason,'')='HISTORICAL_IDENTITY_UNVERIFIED' AND seen.cutover_generation=i.cutover_generation AND seen.source_version=i.source_version AND seen.source_revision=i.source_revision)))) AND NOT EXISTS(SELECT 1 FROM personal_projection_runtime_intents o WHERE o.spreadsheet_id=i.spreadsheet_id AND o.personal_use_id=i.personal_use_id AND o.state IN ('IN_FLIGHT','REVIEW')))) OR
 (OLD.state='DISPATCHED' AND NEW.state='REVIEW') OR
 (OLD.state='APPROVED' AND NEW.state='CANCELLED')
) BEGIN SELECT RAISE(ABORT,'HISTORICAL_MARKER_TRANSITION_INVALID'); END;

CREATE TRIGGER historical_marker_action_transition_audit BEFORE UPDATE OF state ON personal_historical_marker_actions
WHEN OLD.state IS NOT NEW.state AND (NOT EXISTS(SELECT 1 FROM personal_historical_marker_atomic_assertions x WHERE x.assertion_id=OLD.action_id AND x.ok=1) OR NOT EXISTS(SELECT 1 FROM admin_audit audit WHERE audit.entity_key=OLD.personal_use_id AND audit.action=CASE NEW.state WHEN 'DISPATCHED' THEN 'HISTORICAL_MARKER_DISPATCHED' WHEN 'REVIEW' THEN 'HISTORICAL_MARKER_QUARANTINED' WHEN 'VERIFIED' THEN 'HISTORICAL_MARKER_VERIFIED' WHEN 'CANCELLED' THEN 'HISTORICAL_MARKER_CANCELLED' ELSE '' END AND CASE WHEN json_valid(audit.after_json) THEN json_extract(audit.after_json,'$.actionId')=OLD.action_id ELSE 0 END ))
BEGIN SELECT RAISE(ABORT,'HISTORICAL_MARKER_AUDIT_REQUIRED'); END;
CREATE TRIGGER historical_marker_action_time BEFORE UPDATE OF state,updated_at ON personal_historical_marker_actions WHEN OLD.state IS NOT NEW.state AND (length(NEW.updated_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.updated_at) IS NOT NEW.updated_at OR julianday(NEW.updated_at)<julianday(OLD.updated_at) OR abs((julianday(NEW.updated_at)-julianday('now'))*86400)>60) BEGIN SELECT RAISE(ABORT,'HISTORICAL_MARKER_TIME_INVALID'); END;

-- Prevent an unrelated recovery from releasing or verifying the historic
-- target while any marker request or uncertainty is outstanding.
CREATE TRIGGER historical_marker_hold_identity BEFORE UPDATE OF state ON personal_historical_enrollment_intents WHEN NEW.state='VERIFIED' AND EXISTS(SELECT 1 FROM personal_historical_marker_actions a WHERE a.spreadsheet_id=OLD.spreadsheet_id AND a.sheet_name=OLD.sheet_name AND a.state IN ('APPROVED','DISPATCHED','REVIEW')) BEGIN SELECT RAISE(ABORT,'HISTORICAL_MARKER_STILL_OPEN'); END;
CREATE TRIGGER historical_marker_hold_lock BEFORE DELETE ON personal_raw_enrollment_locks WHEN EXISTS(SELECT 1 FROM personal_historical_marker_actions a WHERE a.spreadsheet_id=OLD.spreadsheet_id AND a.sheet_name=OLD.sheet_name AND a.state IN ('APPROVED','DISPATCHED','REVIEW')) BEGIN SELECT RAISE(ABORT,'HISTORICAL_MARKER_STILL_OPEN'); END;
CREATE TRIGGER historical_marker_hold_other_recovery BEFORE INSERT ON personal_historical_recovery_actions WHEN NEW.state='APPROVED' AND EXISTS(SELECT 1 FROM personal_historical_marker_actions a WHERE a.spreadsheet_id=NEW.spreadsheet_id AND a.sheet_name=NEW.sheet_name AND a.state IN ('APPROVED','DISPATCHED','REVIEW')) BEGIN SELECT RAISE(ABORT,'HISTORICAL_MARKER_STILL_OPEN'); END;

CREATE TRIGGER historical_marker_action_time_immutable BEFORE UPDATE OF updated_at ON personal_historical_marker_actions WHEN OLD.state=NEW.state AND OLD.updated_at IS NOT NEW.updated_at BEGIN SELECT RAISE(ABORT,'HISTORICAL_MARKER_AUDIT_REQUIRED'); END;
